define(["core/notification","mod_videoannotation/player"],function(t,r){return{init:()=>{document.querySelectorAll('[data-region="videoannotation-report"]').forEach(o=>{let e;try{e=JSON.parse(o.dataset.config||"{}")}catch(e){return void t.exception(e)}r.create(o,e.player).then(t=>{o.querySelectorAll('[data-action="seek"]').forEach(e=>{e.addEventListener("click",()=>{t.seek(Number(e.dataset.time||0)),o.querySelector('[data-region="player-container"]')?.scrollIntoView({behavior:"smooth",block:"center"})})})}).catch(e=>t.exception(e))})}}});